'use strict';
function installOfficialRanking(){
 const local=rankingRoom;let official=null,pending=null,working=false,deferred=false;
 afterPlayerUnlock=()=>{if(deferred){deferred=false;renderOfficial()}};
 async function api(action,body){if(body&&!registeredAccess())throw Error('登録した本人のパスワードで入ってください。ゲストは投稿できません。');const r=await fetch('/api/rank/'+action,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});let j;try{j=await r.json()}catch{throw Error('オンライン順位へ接続できません。端末内学習は続けられます。')}if(!r.ok)throw Error(j.error||'通信に失敗しました');return j;}
 const departments={pref:'都道府県10問・4択',location:'都道府県の位置10問・地図タップ',capital:'県庁所在地10問・4択',terrain:'地形10問・発展（入門・基本を含む）・4択',mixed:'総合10問・発展（入門・基本を含む）・4択'};
 rankingRoom=()=>{local();app.insertAdjacentHTML('afterbegin','<div class="row"><button id="localRank" disabled>端末内・自分のベスト</button><button id="onlineRank">オンライン公式ランキング</button></div>');$('#onlineRank').onclick=onlineHub;};
 function onlineHub(){view='rankings';app.innerHTML=`${back()}<button id="returnLocal">端末内・自分のベストへ</button><h1>オンライン公式ランキング</h1>${!registeredAccess()?'<p class="notice">ゲストは順位の閲覧のみ利用できます。公式挑戦は登録した本人で入ってから始めてください。</p>':''}<p class="note">通常学習とは別の挑戦です。サーバーが10問を発行し、回答ごとに採点します。ヒントなし・制限は開始から1時間。通常テストの成績には含みません。</p><label for="officialDept">公式部門</label><select id="officialDept">${Object.entries(departments).map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select><p class="note">同点は同順位。表示順は達成日時、識別情報の順です。このブラウザの参加識別は端末内の全プレイヤーで共通で、各部門にベスト1件だけ載ります。ブラウザを変えると別の識別になります。学校名・年齢・連絡先は不要です。</p><button id="officialStart" class="primary" ${registeredAccess()?'':'disabled'}>この名前で公式挑戦を始める</button><button id="officialResume" ${registeredAccess()?'':'disabled'}>通信中断した挑戦を再開</button><button id="reloadBoard">順位を更新・再試行</button><p id="officialNotice" role="status"></p><div id="onlineBoard"></div>`;bindBack();$('#returnLocal').onclick=()=>navigate(rankingRoom);$('#officialStart').onclick=()=>begin();$('#officialResume').onclick=()=>{try{const saved=JSON.parse(sessionStorage.getItem('japan-geography-official-v13'));if(!saved||saved.localPlayer!==player().id||!registeredAccess())throw Error('このプレイヤーの再開できる挑戦はありません。');official=saved;pending=saved.pending||null;renderOfficial();if(pending)sendPending()}catch(e){$('#officialNotice').textContent=e.message}};$('#reloadBoard').onclick=board;$('#officialDept').onchange=board;board();}
 async function board(){try{const dept=$('#officialDept').value;$('#onlineBoard').textContent='順位を読み込んでいます…';const j=await api('leaderboard?department='+encodeURIComponent(dept));if(!$('#onlineBoard')||$('#officialDept').value!==dept)return;$('#onlineBoard').innerHTML=j.rows.map(r=>`<p class="card">${r.rank}位 ${esc(r.nickname)}：${r.right} / ${r.count}問</p>`).join('')||'<p>まだ記録がありません。</p>'}catch(e){if($('#officialNotice'))$('#officialNotice').textContent=e.message}}
 async function begin(){if(working)return;working=true;const actor=player().id,department=$('#officialDept').value,nickname=player().name;$('#officialStart').disabled=true;try{await api('identity',{});if(!registeredAccess()||player().id!==actor)throw Error('プレイヤーが切り替わりました。');const j=await api('start',{department,nickname});official={...j,localPlayer:actor};pending=null;remember();if(view==='rankings'&&player().id===actor)renderOfficial()}catch(e){if($('#officialNotice'))$('#officialNotice').textContent=e.message;if($('#officialStart'))$('#officialStart').disabled=!registeredAccess()}finally{working=false}}
 function remember(){sessionStorage.setItem('japan-geography-official-v13',JSON.stringify(official))}
 function renderOfficial(){if(!official||official.localPlayer!==player().id)return;if(!registeredAccess()){deferred=true;return}view='official';const sq=official.question,q=data.find(q=>q.id===sq.item);game={options:{mode:'test10',official:true,format:sq.mode==='tap'?'tap':'name'},selected:null};app.innerHTML=`${back()}<h2>公式挑戦 ${official.position+1} / 10問</h2><div class="gameLayout"><div class="mapbox">${mapMarkup('quiz',q)}<div class="mapTools"><button id="zoomIn">＋</button><button id="zoomOut">−</button><button id="resetMap">日本全体</button><button id="focusMap">出題地域</button></div></div><section class="question"><h2>${esc(sq.prompt)}</h2><div id="officialChoices">${sq.mode==='tap'?'<p id="selection">地図から選んでください</p><button id="confirmTap" disabled>この場所で回答</button>':sq.options.map(o=>`<button class="wide" data-official-choice="${o.id}">${esc(o.label)}</button>`).join('')}</div><button id="officialSkip">わからない</button><p id="officialStatus" role="status"></p><button id="officialRetry" hidden>同じ回答を再送する</button></section></div>`;bindBack();bindMap(q);document.querySelectorAll('[data-official-choice]').forEach(b=>b.onclick=()=>submit(b.dataset.officialChoice));$('#confirmTap')?.addEventListener('click',()=>{if(game.selected)submit(game.selected)});$('#officialSkip').onclick=()=>submit('skip');$('#officialRetry').onclick=()=>sendPending();}
 async function submit(choice){if(working||!registeredAccess()||official.localPlayer!==player().id)return;pending={run:official.run,position:official.position,question:official.question.id,choice};await sendPending()}
 async function sendPending(){if(working||!pending||!registeredAccess())return;working=true;official.pending=pending;remember();$('#officialChoices')?.querySelectorAll('button').forEach(b=>b.disabled=true);$('#officialSkip').disabled=true;try{const result=await api('answer',pending);pending=null;delete official.pending;official={...official,...result};remember();if(result.done){sessionStorage.removeItem('japan-geography-official-v13');if(view!=='official'||official.localPlayer!==player().id)return;view='results';app.innerHTML=`${back()}<h1>公式挑戦の結果</h1><p>${result.right} / ${result.count}問正解。サーバーで確定しました。</p><button id="officialBoard">オンライン順位を見る</button>`;bindBack();$('#officialBoard').onclick=onlineHub;}else if(view==='official'&&official.localPlayer===player().id)renderOfficial()}catch(e){if($('#officialStatus'))$('#officialStatus').textContent=e.message;if($('#officialRetry'))$('#officialRetry').hidden=false;}finally{working=false}}
}
